const ASSET_PHOTOS={"coupe": "data:image/webp;base64,", "hypercar": "data:image/webp;base64,", "chain": "data:image/webp;base64,", "watch": "data:image/webp;base64,", "canvas": "data:image/webp;base64,", "sculpture": "data:image/webp;base64,", "condo": "data:image/webp;base64,", "villa": "data:image/webp;base64,", "duplex": "data:image/webp;base64,", "block": "data:image/webp;base64,"};
function assetPhoto(x){return ASSET_PHOTOS[x.id]?`<img class="asset-photo" src="${ASSET_PHOTOS[x.id]}" alt="${esc(x.name)}" loading="lazy">`:`<span class="asset-art">${assetIcon(x.icon)}</span>`}
